  /**
   * Returns the OS corresponding to the given platform's OS constraint.
   *
   * <p>Falls back to {@link OS#getCurrent()} if the platform has no OS constraint. Returns {@link
   * OS#UNKNOWN} for constraint values not recognized by Bazel. Both {@code @platforms//os:osx} and
   * {@code @platforms//os:macos} map to {@link OS#DARWIN}.
   */
  public static OS getOsFromConstraintsOrHost(PlatformInfo platformInfo) {
    ConstraintCollection constraintCollection = platformInfo.constraints();
    if (!constraintCollection.has(OS_CONSTRAINT_SETTING)) {
      return OS.getCurrent();
    }
    ConstraintValueInfo osConstraint = constraintCollection.get(OS_CONSTRAINT_SETTING);
    if (MACOS_CONSTRAINT_VALUE.equals(osConstraint)) {
